/* Goldman Snacks: flashcard deck built from the glossary */
window.GS_DECK=[{"t": "Absolute reference", "m": "A cell reference with $ signs, such as $H$1. When you copy the formula to another cell, this reference stays pointing at the same cell.", "e": "=E2*$H$1 copied down one row becomes =E3*$H$1. E2 changed to E3, but $H$1 stayed the same.", "f": "excel-skills.html", "n": "Excel skills", "l": "ind"}, {"t": "Account", "m": "A record that collects every transaction for one item, such as cash, sales or rent. Each account has a debit (left) side and a credit (right) side.", "e": "The Rent account lists every rent payment in the year. Adding them up gives the total rent cost.", "f": "debits-and-credits.html", "n": "Debits, credits and account types", "l": "f"}, {"t": "Accounting estimate", "m": "A figure that needs judgement because the true amount isn’t known yet.", "e": "Useful lives of assets, allowances for bad debts, warranty provisions.", "f": "ias-8-policies-estimates-errors.html", "n": "IAS 8: Policies, estimates and errors", "l": "y3"}, {"t": "Accounting policy", "m": "The rules and methods a company uses to prepare its accounts.", "e": "Valuing inventory using FIFO, or measuring property using the cost model.", "f": "ias-8-policies-estimates-errors.html", "n": "IAS 8: Policies, estimates and errors", "l": "y3"}, {"t": "Accrual", "m": "A cost that belongs to this year, but has not been paid by the year end. It is added to this year’s costs and shown as a liability (an amount owed).", "e": "The December electricity bill arrives in January. It is still a December cost, so it goes in this year’s accounts as an accrual.", "f": "accruals-and-prepayments.html", "n": "Accruals and prepayments", "l": "f"}, {"t": "Accruals concept", "m": "The rule that income and costs go in the year they relate to. The date the cash is paid or received does not decide the year.", "e": "Rent for December is paid on 5 January. It is still December’s cost.", "f": "accruals-and-prepayments.html", "n": "Accruals and prepayments", "l": "f"}, {"t": "Addition", "m": "A long-term asset, such as a machine or a vehicle, that the business bought during the year.", "e": "A new delivery van bought in August for £32,500 is an addition in that year.", "f": "job-audit-fixed-asset-additions.html", "n": "Audit: fixed asset additions", "l": "job"}, {"t": "Adjusting event", "m": "An event after the year end that gives evidence of conditions that existed at the year end. The figures are changed.", "e": "A court case open at the year end is settled for more than the provision.", "f": "ias-10-events-after-reporting-period.html", "n": "IAS 10: Events after the reporting period", "l": "y3"}, {"t": "After-date cash", "m": "Money a customer pays after the year end for a debt they owed at the year end. Auditors use it as evidence that the debt was real.", "e": "A customer owed £10,000 on 31 March and paid £10,000 on 18 April. The payment shows the debt existed.", "f": "job-audit-receivables.html", "n": "Audit: testing receivables", "l": "job"}, {"t": "Alternative performance measure (APM)", "m": "A profit figure (or other figure) that a company defines itself. It is not defined by the accounting rules (IFRS). Companies often call it “adjusted” or “underlying” profit.", "e": "Statutory profit is £20m. The company adds back £5m of restructuring costs and reports “adjusted profit” of £25m.", "f": "reading-an-annual-report.html", "n": "Reading an annual report", "l": "ind"}, {"t": "Amortisation", "m": "Spreading the cost of an intangible asset (one you cannot touch, such as software or a patent) as an expense over the years it is used. It works in the same way as depreciation.", "e": "A patent costing £50,000 that lasts 10 years gives amortisation of £5,000 each year.", "f": "ias-38-intangible-assets.html", "n": "IAS 38: Intangible assets", "l": "y3"}, {"t": "Amortised cost", "m": "A way to measure a loan or bond. Start with the amount borrowed or paid, add interest at the effective interest rate each year, and take off the payments.", "e": "Borrow £9,500. Interest at 5.4% is £513. Pay £400. The new balance is £9,500 + £513 − £400 = £9,613.", "f": "ifrs-9-financial-instruments.html", "n": "IFRS 9: Financial instruments", "l": "y3"}, {"t": "Analytical review", "m": "Working out what a figure should roughly be, then comparing it with the actual figure. A big difference needs an explanation.", "e": "Wages were £1.26m last year. There are 7% more staff and a 4% pay rise, so wages should be about £1.40m. If they are £1.45m, the auditor asks why.", "f": "job-audit-payroll.html", "n": "Audit: payroll", "l": "job"}, {"t": "Annual report", "m": "The document a company publishes once a year. It contains a written review of the business, reports on how it is run, and the audited financial statements.", "e": "A listed company’s annual report is often more than 200 pages. The audited accounts are near the back.", "f": "reading-an-annual-report.html", "n": "Reading an annual report", "l": "ind"}, {"t": "Appropriation account", "m": "A statement showing how a partnership’s profit is split between the partners: salaries first, then interest on capital, then the rest in the agreed ratio.", "e": "Profit £80,000. Salary to one partner £12,000, interest £5,000, and the remaining £63,000 split 3:2.", "f": "partnerships.html", "n": "Partnerships", "l": "f"}, {"t": "Assertion", "m": "A statement that the accounts are making, which the auditor tests. The main ones are: it exists, it is complete, the amount is right, and it is in the right year.", "e": "Showing “Inventory £50,000” makes the assertion that £50,000 of stock really exists and belongs to the business.", "f": "audit-basics.html", "n": "Audit basics", "l": "ind"}, {"t": "Assessment centre", "m": "The final stage of many graduate job applications. It is a half day or full day of tasks, such as a group exercise, a written test, a presentation and an interview.", "e": "A graduate scheme might invite 30 people to an assessment centre and offer jobs to 10.", "f": "interview-prep.html", "n": "Interview prep", "l": "ind"}, {"t": "Asset", "m": "Something the business owns or controls that will bring it money or another benefit in future.", "e": "Cash in the bank, stock to sell, a delivery van, and money customers owe are all assets.", "f": "accounting-equation.html", "n": "The accounting equation", "l": "f"}, {"t": "Associate", "m": "A company in which an investor owns a large share (usually 20% to 50%) and has “significant influence”: a real say in decisions, but not control.", "e": "Owning 30% of a company and having one seat on its board usually makes it an associate.", "f": "group-accounts.html", "n": "Group accounts", "l": "ind"}, {"t": "Auditor’s report", "m": "The auditor’s written opinion, near the front of the financial statements, on whether the accounts give a true and fair view.", "e": "“In our opinion, the financial statements give a true and fair view…” is an unmodified (clean) opinion.", "f": "reading-an-annual-report.html", "n": "Reading an annual report", "l": "ind"}, {"t": "Balance", "m": "The difference between the total of the debit side and the total of the credit side of an account. It shows how much is left.", "e": "Cash account: £3,300 in (debit) and £450 out (credit). The balance is £2,850 debit, so the business has £2,850 of cash.", "f": "debits-and-credits.html", "n": "Debits, credits and account types", "l": "f"}, {"t": "Balance b/d", "m": "“Balance brought down”. The closing balance of an account, written as the first line of the next period. It sits on the opposite side to the balance c/d.", "e": "£2,850 is carried down on the credit side at the end of March, then brought down on the debit side as the opening balance for April.", "f": "t-accounts.html", "n": "T-accounts and balancing off", "l": "f"}, {"t": "Balance c/d", "m": "“Balance carried down”. The amount written on the smaller side of an account at the end of a period so that both sides add up to the same total.", "e": "Debits £3,300 and credits £450. Write £2,850 as “Balance c/d” on the credit side so both sides total £3,300.", "f": "t-accounts.html", "n": "T-accounts and balancing off", "l": "f"}, {"t": "Balancing figure", "m": "A missing number worked out from a total that must be correct. You subtract all the known numbers from the total.", "e": "Assets are £62,700. Liabilities and share capital are £50,700. Retained earnings must be the balancing figure of £12,000.", "f": "incomplete-records.html", "n": "Incomplete records", "l": "f"}, {"t": "Balancing off", "m": "The process at the end of a period of adding up both sides of an account, writing in the balance c/d, and bringing the balance down to the next period.", "e": "At the end of each month, a bookkeeper balances off the cash account to find the closing cash.", "f": "t-accounts.html", "n": "T-accounts and balancing off", "l": "f"}, {"t": "Bank reconciliation", "m": "A statement that explains why the business’s own cash record (the cash book) shows a different balance from the bank statement.", "e": "The cash book shows £4,505 and the bank shows £5,030. The reconciliation shows the difference is a £1,625 cheque not yet cleared, less £1,100 paid in but not yet shown.", "f": "practical-bookkeeping.html", "n": "Practical bookkeeping", "l": "ind"}, {"t": "Best estimate", "m": "The amount a company would realistically have to pay to settle an obligation today. It is used to measure a provision.", "e": "Lawyers think a claim will cost between £80,000 and £120,000, most likely £100,000. The best estimate is £100,000.", "f": "ias-37-provisions.html", "n": "IAS 37: Provisions and contingencies", "l": "y3"}, {"t": "Bonus issue", "m": "Free extra shares given to existing shareholders. No cash comes in, so it is treated as if it happened at the start of the year.", "e": "A 1 for 4 bonus issue turns 4 million shares into 5 million.", "f": "ias-33-earnings-per-share.html", "n": "IAS 33: Earnings per share", "l": "y3"}, {"t": "Borrowing costs", "m": "Interest and other costs of borrowing money.", "e": "Interest on a bank loan taken out to build a factory.", "f": "ias-23-borrowing-costs.html", "n": "IAS 23: Borrowing costs", "l": "y3"}, {"t": "Budget", "m": "A plan, written before the period starts, of the income and costs the business expects.", "e": "The October budget said membership income would be £84,000.", "f": "job-month-end-close.html", "n": "Finance team: month-end close", "l": "job"}, {"t": "Capital allowances", "m": "The tax rules’ version of depreciation. They decide how much of an asset’s cost can be taken off taxable profit, and when.", "e": "A company buys a £55,000 machine. The annual investment allowance lets it deduct all £55,000 from taxable profit in the year of purchase.", "f": "job-tax-vat-corporation-tax.html", "n": "Tax: VAT return and corporation tax", "l": "job"}, {"t": "Capital expenditure", "m": "Money spent to buy a long-term asset, or to improve one so it does more or lasts longer. It goes on the balance sheet, not straight into expenses.", "e": "Adding a new packing module that increases output by 40% is capital expenditure.", "f": "job-audit-fixed-asset-additions.html", "n": "Audit: fixed asset additions", "l": "job"}, {"t": "Capital grant", "m": "A grant related to buying or building a long-term asset.", "e": "A grant for 20% of the cost of new equipment.", "f": "ias-20-government-grants.html", "n": "IAS 20: Government grants", "l": "y3"}, {"t": "Capitalisation rate", "m": "The weighted average interest rate on general borrowings, used when no specific loan funds the asset.", "e": "Loans at 6% and 9% averaging 7.2%.", "f": "ias-23-borrowing-costs.html", "n": "IAS 23: Borrowing costs", "l": "y3"}, {"t": "Capitalise", "m": "Add a cost to an asset in the statement of financial position, instead of treating it as an expense.", "e": "Interest during construction is added to the building’s cost.", "f": "ias-23-borrowing-costs.html", "n": "IAS 23: Borrowing costs", "l": "y3"}, {"t": "Cash equivalents", "m": "Investments that can be turned into a known amount of cash very quickly (usually within 3 months) with very little risk. They are counted together with cash.", "e": "Money in a 3-month bank deposit is a cash equivalent.", "f": "cash-flow-statement-explained.html", "n": "Statement of cash flows", "l": "fs"}, {"t": "Cash flow forecast", "m": "A prediction, month by month, of the cash the business expects to receive and pay, and its bank balance at the end of each month.", "e": "The forecast shows the bank balance reaching £190,000 overdrawn in January.", "f": "job-going-concern.html", "n": "Audit: going concern review", "l": "job"}, {"t": "Cash-generating unit (CGU)", "m": "The smallest group of assets that produces cash on its own. Assets are tested for impairment as a group when they cannot be tested one by one.", "e": "One shop, with its fittings, equipment and share of goodwill, can be a cash-generating unit.", "f": "ias-36-impairment.html", "n": "IAS 36: Impairment of assets", "l": "y3"}, {"t": "Cell reference", "m": "The address of one cell in a spreadsheet: the column letter followed by the row number.", "e": "D2 means column D, row 2.", "f": "excel-skills.html", "n": "Excel skills", "l": "ind"}, {"t": "Closing rate", "m": "The exchange rate at the year end.", "e": "£1 = $1.30 on 31 December.", "f": "ias-21-foreign-currency.html", "n": "IAS 21: Foreign currency transactions", "l": "y3"}, {"t": "Commercial awareness", "m": "Knowing what is happening in business and the economy, and being able to explain how it affects companies and their advisers.", "e": "Explaining that higher interest rates increase clients’ loan costs, so auditors will look more closely at going concern.", "f": "interview-prep.html", "n": "Interview prep", "l": "ind"}, {"t": "Competency question", "m": "An interview question that asks for a real example from your past. It usually starts with “Tell me about a time when…”.", "e": "“Tell me about a time you found a mistake.” Answer with a real example using STAR.", "f": "interview-prep.html", "n": "Interview prep", "l": "ind"}, {"t": "Component depreciation", "m": "Depreciating the main parts of one asset separately when they last for different lengths of time.", "e": "An aircraft’s engines last 8 years and its body lasts 25 years, so each part is depreciated over its own life.", "f": "ias-16-property-plant-equipment.html", "n": "IAS 16: Property, plant and equipment", "l": "y3"}, {"t": "Consolidation", "m": "Combining the accounts of a parent company and the companies it controls (subsidiaries) into one set of accounts, as if they were one business.", "e": "The group accounts add 100% of each subsidiary’s assets to the parent’s, then remove any trading between them.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Constructive obligation", "m": "A duty to pay that comes from how the company has behaved, not from the law or a contract. Other people reasonably expect the company to pay.", "e": "A shop has always refunded unhappy customers and says so in its adverts. It has a constructive obligation to keep doing it.", "f": "ias-37-provisions.html", "n": "IAS 37: Provisions and contingencies", "l": "y3"}, {"t": "Contingent liability", "m": "A possible obligation that depends on a future event, or one that is not probable. It is described in the notes to the accounts, but not included in the figures.", "e": "A customer is suing the company, and lawyers say the company will probably win. The claim is disclosed as a contingent liability.", "f": "ias-37-provisions.html", "n": "IAS 37: Provisions and contingencies", "l": "y3"}, {"t": "Contract liability", "m": "Money a customer has paid before the business has done the work or delivered the goods. It is a liability until the work is done.", "e": "A member pays £600 in January for a year. After one month, £550 is still a contract liability.", "f": "ifrs-15-revenue.html", "n": "IFRS 15: Revenue in depth", "l": "y3"}, {"t": "Control account", "m": "One account that shows the total of many individual accounts, such as all customers’ balances. It is used to check the individual accounts are right.", "e": "The sales ledger control account shows £412,600. The individual customer balances should add up to the same £412,600.", "f": "practical-bookkeeping.html", "n": "Practical bookkeeping", "l": "ind"}, {"t": "Cost model", "m": "Showing an asset in the accounts at what it cost, minus the depreciation charged so far.", "e": "A machine cost £20,000 and has £8,000 of depreciation, so it is shown at £12,000.", "f": "ias-16-property-plant-equipment.html", "n": "IAS 16: Property, plant and equipment", "l": "y3"}, {"t": "Cost of sales", "m": "The cost of the goods that were actually sold during the period. It is calculated as opening stock + purchases − closing stock.", "e": "Opening stock £1,500 + purchases £9,000 − closing stock £2,000 = cost of sales £8,500.", "f": "income-statement.html", "n": "Income statement", "l": "f"}, {"t": "Count memo", "m": "The auditor’s written record of what happened at the client’s stock count: how it was run, the test counts done, and any problems found.", "e": "“The count was well organised, but the supervisor counted aisle 4 alone.”", "f": "job-inventory-count.html", "n": "Audit: inventory count", "l": "job"}, {"t": "Count sheet", "m": "The client’s form listing each stock item and the quantity counted at the stock count.", "e": "The count sheet says 260 bags of Ethiopian beans.", "f": "job-inventory-count.html", "n": "Audit: inventory count", "l": "job"}, {"t": "Covenant", "m": "A condition in a loan agreement that the borrower must keep to. If it is broken, the lender may be able to demand the money back.", "e": "“Operating profit must be at least 3 times the interest cost.” A result of 2.63 times breaks the covenant.", "f": "job-going-concern.html", "n": "Audit: going concern review", "l": "job"}, {"t": "Credit (Cr)", "m": "The right-hand side of an account. A credit increases a liability, income or capital account, and decreases an asset or expense account.", "e": "When a business receives £1,000 of sales in cash, Sales is credited with £1,000.", "f": "debits-and-credits.html", "n": "Debits, credits and account types", "l": "f"}, {"t": "Criteria", "m": "In a spreadsheet formula, the condition a row must meet to be included.", "e": "In =SUMIFS(D:D,E:E,\"Unpaid\"), the criteria is \"Unpaid\".", "f": "excel-skills.html", "n": "Excel skills", "l": "ind"}, {"t": "Current", "m": "Expected to be turned into cash, used up or paid within 12 months of the year end.", "e": "Stock and money owed by customers are current assets. A supplier bill due next month is a current liability.", "f": "statement-of-financial-position.html", "n": "Statement of financial position", "l": "f"}, {"t": "Current account", "m": "In a partnership, each partner’s account for their salary, interest, share of profit, and the money they take out (drawings).", "e": "A partner is credited with a £40,800 profit share and debited with £30,000 of drawings.", "f": "partnerships.html", "n": "Partnerships", "l": "f"}, {"t": "Current tax", "m": "The tax a company must pay on this year’s taxable profit.", "e": "Taxable profit £401,900 × 25% = £100,475 of current tax.", "f": "ias-12-deferred-tax.html", "n": "IAS 12: Deferred tax", "l": "y3"}, {"t": "Cut-off", "m": "Making sure each transaction is recorded in the correct year, especially transactions close to the year end.", "e": "Goods sent to a customer on 31 March belong in the year ending 31 March, even if the invoice is dated 2 April.", "f": "job-audit-receivables.html", "n": "Audit: testing receivables", "l": "job"}, {"t": "Date of authorisation", "m": "The date the directors approve the accounts for issue. Events after this are ignored.", "e": "The board signs the accounts on 15 March.", "f": "ias-10-events-after-reporting-period.html", "n": "IAS 10: Events after the reporting period", "l": "y3"}, {"t": "Debit (Dr)", "m": "The left-hand side of an account. A debit increases an asset or expense account, and decreases a liability, income or capital account.", "e": "When a business pays £300 of rent, Rent is debited with £300.", "f": "debits-and-credits.html", "n": "Debits, credits and account types", "l": "f"}, {"t": "Deferred income", "m": "Money received now for goods or services the business will provide in a later period. It is a liability until it is earned.", "e": "£600 of rent received in December for January to March is deferred income at 31 December.", "f": "accruals-and-prepayments.html", "n": "Accruals and prepayments", "l": "f"}, {"t": "Deferred tax", "m": "Tax that will be paid (or saved) in future years because the accounts and the tax rules count some items in different years.", "e": "Tax relief on a machine was given all in year 1, but the accounts spread the cost over 5 years. More tax will be paid later, so a deferred tax liability is recorded.", "f": "ias-12-deferred-tax.html", "n": "IAS 12: Deferred tax", "l": "y3"}, {"t": "Depreciation", "m": "Spreading the cost of a physical long-term asset, such as a van or machine, as an expense over the years it is used.", "e": "A £10,000 van used for 5 years and then worth nothing: straight-line depreciation is £2,000 each year.", "f": "depreciation.html", "n": "Depreciation and disposals", "l": "f"}, {"t": "Development", "m": "Using research results to design or build a specific new product or process. Its cost can be recorded as an asset once strict conditions are met.", "e": "Building and testing a new app after proving the idea works.", "f": "ias-38-intangible-assets.html", "n": "IAS 38: Intangible assets", "l": "y3"}, {"t": "Diluted EPS", "m": "EPS recalculated as if convertible loans, options and similar items had turned into shares.", "e": "Options that would create 500,000 more shares lower EPS.", "f": "ias-33-earnings-per-share.html", "n": "IAS 33: Earnings per share", "l": "y3"}, {"t": "Dividend", "m": "A payment of profit from a company to its shareholders. It reduces retained earnings. It is not an expense.", "e": "A company with £480,000 of profit pays dividends of £150,000 and keeps £330,000.", "f": "company-profit-or-loss-explained.html", "n": "Company statement of profit or loss and OCI", "l": "fs"}, {"t": "Drawings", "m": "Money or goods the owner of a business takes out for their own personal use. Drawings reduce the owner’s capital. They are not a business expense.", "e": "A sole trader takes £200 from the till to buy personal shopping. That is £200 of drawings.", "f": "statement-of-financial-position.html", "n": "Statement of financial position", "l": "f"}, {"t": "Earnings per share (EPS)", "m": "Profit attributable to ordinary shareholders divided by the weighted average number of ordinary shares.", "e": "£1,200,000 ÷ 4,250,000 shares = 28.2p.", "f": "ias-33-earnings-per-share.html", "n": "IAS 33: Earnings per share", "l": "y3"}, {"t": "EBITDA", "m": "A profit figure calculated before taking off interest, tax, depreciation and amortisation. Lenders and analysts use it as a rough measure of cash-like profit.", "e": "Operating profit £300,000 + depreciation £50,000 = EBITDA £350,000.", "f": "job-new-lease-ifrs16.html", "n": "Finance team: accounting for a new lease", "l": "job"}, {"t": "Effective interest rate", "m": "The single interest rate that spreads the total cost of a loan evenly over its life, including any fees or discount, not just the stated interest.", "e": "A bond pays 4% interest, but the company only received £9,500 for £10,000 of bonds. The effective rate works out as 5.4%.", "f": "ifrs-9-financial-instruments.html", "n": "IFRS 9: Financial instruments", "l": "y3"}, {"t": "Employer’s National Insurance", "m": "National Insurance that the employer pays to HMRC on top of employees’ wages. It is an extra cost to the business.", "e": "An employee earns £3,000 a month. The employer pays its own National Insurance on top, which is not taken from the employee’s pay.", "f": "job-audit-payroll.html", "n": "Audit: payroll", "l": "job"}, {"t": "Equity (capital)", "m": "The owner’s share of the business: the money the owner put in, plus profits kept in the business, minus drawings. It equals assets minus liabilities.", "e": "Assets £50,000 − liabilities £18,000 = equity £32,000.", "f": "accounting-equation.html", "n": "The accounting equation", "l": "f"}, {"t": "Error of omission", "m": "A transaction that was left out of the books completely. The trial balance still agrees, because neither side was recorded.", "e": "A £200 rent payment that nobody recorded.", "f": "trial-balance.html", "n": "Trial balance", "l": "f"}, {"t": "Exception", "m": "In an audit, an item where the evidence does not match the client’s records. Each exception needs to be investigated.", "e": "An employee who left in January is still being paid. That is an exception.", "f": "job-audit-receivables.html", "n": "Audit: testing receivables", "l": "job"}, {"t": "Exempt", "m": "For VAT: a type of sale that is outside VAT. No VAT is charged, and VAT on related costs usually cannot be reclaimed.", "e": "Insurance is exempt from VAT.", "f": "job-tax-vat-corporation-tax.html", "n": "Tax: VAT return and corporation tax", "l": "job"}, {"t": "Existence", "m": "The audit check that an asset or balance in the accounts is real.", "e": "The auditor finds stock listed on the count sheet on the warehouse shelf. That tests existence.", "f": "job-audit-receivables.html", "n": "Audit: testing receivables", "l": "job"}, {"t": "Expected credit loss", "m": "The amount a business expects to lose because some customers or borrowers will not pay. It is set aside as an allowance before they fail to pay.", "e": "£100,000 of receivables with an expected 2% loss rate gives an allowance of £2,000.", "f": "ifrs-9-financial-instruments.html", "n": "IFRS 9: Financial instruments", "l": "y3"}, {"t": "External audit", "m": "An independent check of a company’s financial statements by a qualified auditor from outside the company, who then gives an opinion on them.", "e": "An audit firm checks a company’s accounts every year and signs the auditor’s report.", "f": "audit-basics.html", "n": "Audit basics", "l": "ind"}, {"t": "Fair value", "m": "The price an asset would sell for (or a liability would cost to transfer) in a normal sale between willing parties on the measurement date.", "e": "A building bought for £500,000 would sell for £800,000 today. Its fair value is £800,000.", "f": "ifrs-standards.html", "n": "IFRS standards", "l": "y3"}, {"t": "Fair value hierarchy", "m": "Three levels ranking the inputs used to measure fair value, from quoted prices (Level 1) to unobservable estimates (Level 3).", "e": "Quoted shares are Level 1; a model using the company’s own forecasts is Level 3.", "f": "ifrs-13-fair-value.html", "n": "IFRS 13: Fair value measurement", "l": "y3"}, {"t": "Fair value model", "m": "Investment property is remeasured to fair value each year, with gains and losses in profit or loss and no depreciation.", "e": "A £30,000 rise in value is shown as a gain in profit.", "f": "ias-40-investment-property.html", "n": "IAS 40: Investment property", "l": "y3"}, {"t": "Favourable / adverse", "m": "Words used to describe a variance. Favourable means the result is better than budget. Adverse means it is worse than budget.", "e": "Income £14,600 against a budget of £12,000 is £2,600 favourable. Costs £43,900 against a budget of £41,000 is £2,900 adverse.", "f": "job-month-end-close.html", "n": "Finance team: month-end close", "l": "job"}, {"t": "Financial asset", "m": "A contract that gives a right to receive cash (or another financial asset), such as money owed by customers, a loan given, or shares held.", "e": "A £5,000 invoice a customer has not yet paid is a financial asset.", "f": "ifrs-9-financial-instruments.html", "n": "IFRS 9: Financial instruments", "l": "y3"}, {"t": "Financial year", "m": "The 12-month period the accounts cover. It does not have to match the calendar year.", "e": "A financial year from 1 April 2025 to 31 March 2026.", "f": "start-here.html", "n": "Start here", "l": ""}, {"t": "Financing activities", "m": "In the statement of cash flows: cash received from or paid to the business’s owners and lenders.", "e": "Issuing new shares for £10,000 and repaying £8,000 of a loan are financing activities.", "f": "cash-flow-statement-explained.html", "n": "Statement of cash flows", "l": "fs"}, {"t": "Functional currency", "m": "The currency of the main economic environment the company operates in.", "e": "Pounds sterling for a UK retailer.", "f": "ias-21-foreign-currency.html", "n": "IAS 21: Foreign currency transactions", "l": "y3"}, {"t": "Gearing", "m": "How much of a business’s long-term funding comes from borrowing, as a percentage.", "e": "Loans £40,000 and equity £60,000: gearing = 40,000 ÷ 100,000 = 40%.", "f": "ratio-analysis.html", "n": "Ratio analysis", "l": "y3"}, {"t": "Ghost employee", "m": "A person being paid through the payroll who does not really work for the business, such as a former employee still being paid, or a fake name. It can be an error or fraud.", "e": "An employee left in January, but salary payments kept going to a bank account in February and March.", "f": "job-audit-payroll.html", "n": "Audit: payroll", "l": "job"}, {"t": "Going concern", "m": "The assumption that a business will keep operating for at least the next 12 months and will not have to close or sell off its assets. Accounts are normally prepared on this basis.", "e": "If a company’s bank is about to withdraw its overdraft and it has no other money, it may not be a going concern.", "f": "job-going-concern.html", "n": "Audit: going concern review", "l": "job"}, {"t": "Goods received note (GRN)", "m": "A document created when goods arrive, recording what was delivered and when.", "e": "GRN-889 records 200 bags of beans delivered at 5:30pm on 31 March.", "f": "job-inventory-count.html", "n": "Audit: inventory count", "l": "job"}, {"t": "Goodwill", "m": "The amount paid for a business that is more than the fair value of its identifiable net assets. It represents things like reputation, customers and staff.", "e": "A company pays £500,000 for a business whose net assets are worth £390,000. Goodwill is £110,000.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Government grant", "m": "Help from government in the form of money or assets, given in return for meeting conditions.", "e": "£20,000 towards buying a new machine.", "f": "ias-20-government-grants.html", "n": "IAS 20: Government grants", "l": "y3"}, {"t": "Gross profit", "m": "Sales minus the cost of the goods sold, before any other expenses are taken off.", "e": "Sales £20,000 − cost of sales £8,500 = gross profit £11,500.", "f": "income-statement.html", "n": "Income statement", "l": "f"}, {"t": "Headroom", "m": "The amount by which an asset’s recoverable amount is higher than its value in the accounts. Small headroom means a small change could cause an impairment.", "e": "Goodwill of £84m and recoverable amount of £90.2m gives headroom of £6.2m (about 7%).", "f": "ias-36-impairment.html", "n": "IAS 36: Impairment of assets", "l": "y3"}, {"t": "Identified asset", "m": "In a lease, the specific asset the contract is for, such as a named machine or a particular building.", "e": "A contract for “machines serial numbers 101 to 110” has identified assets. A contract for “a cleaning service” does not.", "f": "job-new-lease-ifrs16.html", "n": "Finance team: accounting for a new lease", "l": "job"}, {"t": "IFRS / IAS", "m": "International Financial Reporting Standards: the rules that set how companies measure and present their figures. Older standards are called IAS. Both are still in use.", "e": "IAS 2 is the standard for inventory. IFRS 16 is the standard for leases.", "f": "ifrs-standards.html", "n": "IFRS standards", "l": "y3"}, {"t": "Impairment", "m": "A write-down of an asset because it is worth less than the value shown in the accounts. The write-down is an expense.", "e": "Shop fittings are in the accounts at £200,000, but they are only worth £120,000. The impairment is £80,000.", "f": "ias-36-impairment.html", "n": "IAS 36: Impairment of assets", "l": "y3"}, {"t": "Incomplete records", "m": "Accounting records that do not use full double entry, often kept by small businesses. The accountant has to work out the missing figures.", "e": "A market trader keeps only bank statements and a box of receipts.", "f": "incomplete-records.html", "n": "Incomplete records", "l": "f"}, {"t": "Incremental borrowing rate", "m": "The interest rate a company would pay to borrow a similar amount, for a similar time, with similar security. It is used to discount lease payments when the lease’s own rate is not known.", "e": "Northwell would pay 7% to borrow for 5 years, so 7% is used for its 5-year lease.", "f": "ifrs-16-leases.html", "n": "IFRS 16: Lease calculations", "l": "y3"}, {"t": "Indefinite useful life", "m": "When there is no foreseeable end to the time an intangible asset will bring benefits. The asset is not amortised, but it is tested for impairment every year.", "e": "A broadcasting licence that can be renewed forever at little cost may have an indefinite useful life.", "f": "ias-38-intangible-assets.html", "n": "IAS 38: Intangible assets", "l": "y3"}, {"t": "Indirect method", "m": "A way to work out operating cash flow. Start with profit, then add back items that did not use cash (such as depreciation) and adjust for changes in stock, receivables and payables.", "e": "Profit £50,000 + depreciation £12,000 − increase in stock £4,000 = £58,000 so far.", "f": "cash-flow-statement-explained.html", "n": "Statement of cash flows", "l": "fs"}, {"t": "Input VAT", "m": "VAT a business pays on its purchases. A VAT-registered business can usually claim it back from HMRC.", "e": "Buying £1,000 of materials plus £200 VAT: the £200 is input VAT.", "f": "practical-bookkeeping.html", "n": "Practical bookkeeping", "l": "ind"}, {"t": "Intangible asset", "m": "A long-term asset with no physical form that can be separated or comes from a legal right, such as software, patents or licences.", "e": "A patent bought for £50,000.", "f": "ias-38-intangible-assets.html", "n": "IAS 38: Intangible assets", "l": "y3"}, {"t": "Interest on capital", "m": "In a partnership, an amount given to each partner based on the capital they invested. It is a way of sharing profit, not an expense.", "e": "5% interest on £60,000 of capital gives the partner £3,000.", "f": "partnerships.html", "n": "Partnerships", "l": "f"}, {"t": "Intra-group", "m": "Between companies in the same group, such as a parent selling goods to its subsidiary.", "e": "The parent sells £40,000 of goods to its subsidiary. That is an intra-group sale.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Inventory", "m": "Goods the business holds to sell, and materials it will use to make goods. Also called stock.", "e": "A coffee roaster’s unsold bags of coffee beans.", "f": "income-statement.html", "n": "Income statement", "l": "f"}, {"t": "Investing activities", "m": "In the statement of cash flows: cash paid for, or received from selling, long-term assets and investments.", "e": "Buying equipment for £30,000 and selling an old van for £5,000 are investing activities.", "f": "cash-flow-statement-explained.html", "n": "Statement of cash flows", "l": "fs"}, {"t": "Investment property", "m": "Land or buildings held to earn rent, for capital growth, or both.", "e": "An office block leased to other businesses.", "f": "ias-40-investment-property.html", "n": "IAS 40: Investment property", "l": "y3"}, {"t": "Journal", "m": "The record where each transaction is first written down, showing which account is debited and which is credited, with a short explanation.", "e": "Dr Rent £850, Cr Cash £850 (Rent paid by bank transfer).", "f": "journal-entries.html", "n": "Journal entries", "l": "f"}, {"t": "Key audit matter (KAM)", "m": "An area the auditor judged most important in the audit, described in the auditor’s report with what they did about it.", "e": "“Carrying value of goodwill in the Homeware division” as a key audit matter.", "f": "reading-an-annual-report.html", "n": "Reading an annual report", "l": "ind"}, {"t": "Lease incentive", "m": "A payment or benefit that the owner of an asset gives to the business renting it, to encourage it to sign the lease.", "e": "The lessor pays Northwell £3,000 in cash for signing the equipment lease.", "f": "job-new-lease-ifrs16.html", "n": "Finance team: accounting for a new lease", "l": "job"}, {"t": "Lease liability", "m": "The amount a lessee owes for a lease, measured as the present value (today’s value) of the lease payments still to be made.", "e": "5 payments of £24,000 discounted at 7% gives a lease liability of £98,405.", "f": "ifrs-16-leases.html", "n": "IFRS 16: Lease calculations", "l": "y3"}, {"t": "Ledger", "m": "The complete set of a business’s accounts, such as cash, sales, rent and receivables.", "e": "The general ledger contains every account used to prepare the trial balance.", "f": "t-accounts.html", "n": "T-accounts and balancing off", "l": "f"}, {"t": "Lessee", "m": "The business that rents an asset under a lease and pays for using it.", "e": "Northwell Fitness rents gym machines, so it is the lessee.", "f": "ifrs-16-leases.html", "n": "IFRS 16: Lease calculations", "l": "y3"}, {"t": "Liability", "m": "An amount the business owes to someone else, which it will have to pay in future.", "e": "A bank loan, an unpaid supplier invoice and tax owed to HMRC are liabilities.", "f": "accounting-equation.html", "n": "The accounting equation", "l": "f"}, {"t": "Liquidity", "m": "Whether a business has enough cash, or items that will soon become cash, to pay its bills when they are due.", "e": "Current assets £25,000 and current liabilities £12,500 give a current ratio of 2 : 1, which shows good liquidity.", "f": "ratio-analysis.html", "n": "Ratio analysis", "l": "y3"}, {"t": "Low-value asset", "m": "A cheap asset, such as a laptop or tablet. A lessee can choose to expense its lease payments instead of putting the lease on the balance sheet.", "e": "Leasing 4 tablets for reception.", "f": "ifrs-16-leases.html", "n": "IFRS 16: Lease calculations", "l": "y3"}, {"t": "Management accounts", "m": "Internal reports, usually monthly, that show managers and directors how the business is performing against its budget. They are not published.", "e": "The October management accounts show profit of £27,650 against a budget of £32,500.", "f": "job-month-end-close.html", "n": "Finance team: month-end close", "l": "job"}, {"t": "Management letter", "m": "A letter from the auditor to the client’s management that lists weaknesses in the client’s controls and recommends improvements.", "e": "“Leavers are not always removed from the payroll promptly. We recommend a monthly check against HR records.”", "f": "job-audit-payroll.html", "n": "Audit: payroll", "l": "job"}, {"t": "Margin", "m": "Profit as a percentage of the selling price.", "e": "Selling for £125 something that cost £100: profit £25 ÷ price £125 = 20% margin.", "f": "incomplete-records.html", "n": "Incomplete records", "l": "f"}, {"t": "Mark-up", "m": "Profit as a percentage of the cost.", "e": "Selling for £125 something that cost £100: profit £25 ÷ cost £100 = 25% mark-up.", "f": "incomplete-records.html", "n": "Incomplete records", "l": "f"}, {"t": "Material misstatement", "m": "An error (or group of errors) in the accounts that is big enough to change the decisions of someone reading them.", "e": "If materiality is £120,000, an error of £200,000 in revenue is a material misstatement.", "f": "audit-basics.html", "n": "Audit basics", "l": "ind"}, {"t": "Material uncertainty", "m": "A serious doubt about whether a business can continue operating for the next 12 months. It must be explained in the accounts, and the auditor highlights it.", "e": "The bank has not confirmed it will renew the overdraft the company needs, so there is a material uncertainty.", "f": "job-going-concern.html", "n": "Audit: going concern review", "l": "job"}, {"t": "Measure", "m": "To decide the amount at which an item is shown in the accounts.", "e": "Inventory is measured at the lower of cost and net realisable value.", "f": "ifrs-standards.html", "n": "IFRS standards", "l": "y3"}, {"t": "Monetary item", "m": "Money held, or amounts to be received or paid in a fixed number of currency units.", "e": "Cash, trade receivables and payables, loans.", "f": "ias-21-foreign-currency.html", "n": "IAS 21: Foreign currency transactions", "l": "y3"}, {"t": "Month-end close", "m": "The process a finance team follows at the end of each month to make the accounts complete and correct: posting accruals and prepayments, reconciling the bank, and reviewing the results.", "e": "On the first working days of November, the team closes October’s accounts.", "f": "job-month-end-close.html", "n": "Finance team: month-end close", "l": "job"}, {"t": "Most advantageous market", "m": "The market giving the best net amount after transaction and transport costs. Used only if there is no principal market.", "e": "The market where selling nets £22, not £21.", "f": "ifrs-13-fair-value.html", "n": "IFRS 13: Fair value measurement", "l": "y3"}, {"t": "Narration", "m": "A short written explanation under a journal entry that says what the entry is for.", "e": "“(Rent paid by bank transfer)” under Dr Rent, Cr Cash.", "f": "journal-entries.html", "n": "Journal entries", "l": "f"}, {"t": "Net assets", "m": "Total assets minus total liabilities. It equals the owner’s equity.", "e": "Assets £12,500 − liabilities £900 = net assets £11,600.", "f": "statement-of-financial-position.html", "n": "Statement of financial position", "l": "f"}, {"t": "Net book value (NBV)", "m": "An asset’s cost minus all the depreciation charged on it so far. It is the value shown in the accounts.", "e": "A van cost £12,000 and has £3,000 of depreciation, so its net book value is £9,000.", "f": "depreciation.html", "n": "Depreciation and disposals", "l": "f"}, {"t": "Net profit", "m": "What is left from sales after taking off the cost of sales and all the other expenses, such as rent and wages.", "e": "Gross profit £11,500 − expenses £6,900 = net profit £4,600.", "f": "income-statement.html", "n": "Income statement", "l": "f"}, {"t": "Non-adjusting event", "m": "An event after the year end about conditions that arose after it. Disclosed in the notes if material, not adjusted.", "e": "A warehouse is destroyed by fire in February.", "f": "ias-10-events-after-reporting-period.html", "n": "IAS 10: Events after the reporting period", "l": "y3"}, {"t": "Non-controlling interest", "m": "The part of a subsidiary that is owned by shareholders outside the group.", "e": "A parent owns 80% of a subsidiary. The other 20% is the non-controlling interest.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Non-current", "m": "Expected to be kept, used or owed for more than 12 months after the year end.", "e": "A delivery van is a non-current asset. A bank loan repayable in 5 years is a non-current liability.", "f": "statement-of-financial-position.html", "n": "Statement of financial position", "l": "f"}, {"t": "Non-current asset", "m": "An asset the business keeps and uses for more than a year, such as buildings, machinery or vehicles.", "e": "A delivery van used for 5 years.", "f": "depreciation.html", "n": "Depreciation and disposals", "l": "f"}, {"t": "Non-monetary item", "m": "Items not settled in a fixed amount of money.", "e": "Machinery, inventory, prepayments.", "f": "ias-21-foreign-currency.html", "n": "IAS 21: Foreign currency transactions", "l": "y3"}, {"t": "Normal balance", "m": "The side (debit or credit) that an account’s balance is usually on. Assets and expenses are normally debit. Liabilities, income and capital are normally credit.", "e": "The Cash account normally has a debit balance. Trade payables normally has a credit balance.", "f": "trial-balance.html", "n": "Trial balance", "l": "f"}, {"t": "NRV", "m": "Net realisable value: what an item of stock is expected to sell for, minus the costs of finishing and selling it. Stock is valued at the lower of cost and NRV.", "e": "Gift tins sell for £4.50 and cost £0.50 each to sell, so NRV is £4.00. They cost £6.00, so they are valued at £4.00.", "f": "ifrs-standards.html", "n": "IFRS standards", "l": "y3"}, {"t": "On credit", "m": "Bought or sold now, with payment made later. It creates an amount owed.", "e": "Selling £1,200 of goods on credit means the customer will pay later. Until then they owe £1,200 (a trade receivable).", "f": "journal-entries.html", "n": "Journal entries", "l": "f"}, {"t": "Onerous contract", "m": "A contract where the costs the business cannot avoid are more than the benefits it will get. The expected loss is provided for now.", "e": "A company is locked into renting an empty office for £50,000 more than it can earn from subletting it.", "f": "ias-37-provisions.html", "n": "IAS 37: Provisions and contingencies", "l": "y3"}, {"t": "Operating activities", "m": "In the statement of cash flows: cash from the business’s normal day-to-day trading, such as cash from customers and payments to staff and suppliers.", "e": "Cash received from customers of £400,000 is an operating cash flow.", "f": "cash-flow-statement-explained.html", "n": "Statement of cash flows", "l": "fs"}, {"t": "Other comprehensive income", "m": "Gains and losses that are recorded in the accounts but are not included in profit for the year, such as a gain from revaluing a building. They are shown in a separate section under profit.", "e": "A company’s building is revalued up by £150,000. The £150,000 is other comprehensive income, not profit.", "f": "company-profit-or-loss-explained.html", "n": "Company statement of profit or loss and OCI", "l": "fs"}, {"t": "Output VAT", "m": "VAT a business charges its customers on its sales. It is paid to HMRC.", "e": "A sale of £1,000 plus £200 VAT: the £200 is output VAT.", "f": "practical-bookkeeping.html", "n": "Practical bookkeeping", "l": "ind"}, {"t": "Owner-occupied property", "m": "Property the company uses itself. It is covered by IAS 16, not IAS 40.", "e": "The company’s own head office.", "f": "ias-40-investment-property.html", "n": "IAS 40: Investment property", "l": "y3"}, {"t": "Parent", "m": "A company that controls one or more other companies (its subsidiaries).", "e": "P owns 80% of S and controls it, so P is the parent.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Partnership agreement", "m": "The written agreement between partners that sets out how profits are shared, including salaries, interest on capital and the profit-sharing ratio.", "e": "The agreement says profits are shared 3:2 after a £12,000 salary to one partner.", "f": "partnerships.html", "n": "Partnerships", "l": "f"}, {"t": "PAYE", "m": "Pay As You Earn: income tax that an employer takes from employees’ pay and pays to HMRC for them.", "e": "£21,400 of PAYE is taken from March wages and paid to HMRC by 22 April.", "f": "job-audit-payroll.html", "n": "Audit: payroll", "l": "job"}, {"t": "Performance obligation", "m": "A promise in a contract to give the customer a separate good or service. Revenue is recognised as each promise is completed.", "e": "A contract for a phone and 12 months of airtime has two performance obligations.", "f": "ifrs-15-revenue.html", "n": "IFRS 15: Revenue in depth", "l": "y3"}, {"t": "Permanent difference", "m": "An item that is treated differently in the accounts and for tax, and the difference never reverses. No deferred tax arises.", "e": "A parking fine is an expense in the accounts but is never allowed for tax.", "f": "ias-12-deferred-tax.html", "n": "IAS 12: Deferred tax", "l": "y3"}, {"t": "Pivot table", "m": "A spreadsheet tool that groups a list of data by category and shows totals, without writing formulas.", "e": "Turning 5,000 invoices into a small table of total sales by region and by status.", "f": "excel-skills.html", "n": "Excel skills", "l": "ind"}, {"t": "Posting", "m": "Copying each entry from the journal into the correct ledger accounts.", "e": "Dr Rent £850 is posted to the debit side of the Rent account.", "f": "journal-entries.html", "n": "Journal entries", "l": "f"}, {"t": "Prepayment", "m": "A cost paid this year that belongs to next year. It is taken out of this year’s costs and shown as an asset.", "e": "£1,200 of insurance paid on 1 October for 12 months: 9 months (£900) belong to next year, so £900 is a prepayment.", "f": "accruals-and-prepayments.html", "n": "Accruals and prepayments", "l": "f"}, {"t": "Principal market", "m": "The market with the greatest volume and level of activity for the asset.", "e": "The main exchange where a commodity is traded.", "f": "ifrs-13-fair-value.html", "n": "IFRS 13: Fair value measurement", "l": "y3"}, {"t": "Prior period error", "m": "A mistake in earlier accounts, such as a miscount, a misapplied policy or fraud.", "e": "Last year’s closing inventory was counted twice.", "f": "ias-8-policies-estimates-errors.html", "n": "IAS 8: Policies, estimates and errors", "l": "y3"}, {"t": "Profit", "m": "Income minus expenses for a period.", "e": "Income £96,000 − expenses £63,500 = profit £32,500.", "f": "start-here.html", "n": "Start here", "l": ""}, {"t": "Profit attributable to NCI", "m": "The part of the group’s profit for the year that belongs to the outside shareholders of the subsidiaries.", "e": "A subsidiary makes £38,000 profit and outsiders own 20%, so £7,600 is attributable to the non-controlling interest.", "f": "consolidated-profit-or-loss.html", "n": "Consolidated statement of profit or loss", "l": "y3"}, {"t": "Profit-sharing ratio", "m": "The proportions in which partners split the profit left after salaries and interest.", "e": "A ratio of 3:2 means one partner gets 3/5 and the other gets 2/5.", "f": "partnerships.html", "n": "Partnerships", "l": "f"}, {"t": "Proposed adjustment", "m": "A correction the auditor asks the client to make to its accounts, usually as a journal entry.", "e": "Dr Sales £20,000, Cr Trade receivables £20,000 to move a sale into the correct year.", "f": "job-audit-receivables.html", "n": "Audit: testing receivables", "l": "job"}, {"t": "Prospective", "m": "Applied only from now on. Past figures are left alone.", "e": "A change in useful life affects this year’s and future depreciation only.", "f": "ias-8-policies-estimates-errors.html", "n": "IAS 8: Policies, estimates and errors", "l": "y3"}, {"t": "Provision", "m": "A liability where the amount or the timing is not certain, such as expected warranty repairs or a legal claim the company will probably lose.", "e": "A warranty provision of £22,500 for expected repairs on products already sold.", "f": "ias-37-provisions.html", "n": "IAS 37: Provisions and contingencies", "l": "y3"}, {"t": "Qualifying asset", "m": "An asset that takes a substantial period of time to get ready for use or sale.", "e": "A factory, a power station, or whisky that matures for years.", "f": "ias-23-borrowing-costs.html", "n": "IAS 23: Borrowing costs", "l": "y3"}, {"t": "Range", "m": "A block of cells in a spreadsheet, written as the first cell and the last cell with a colon between them.", "e": "D2:D50 means every cell in column D from row 2 to row 50.", "f": "excel-skills.html", "n": "Excel skills", "l": "ind"}, {"t": "Reasonable assurance", "m": "The level of confidence an audit gives: high, but not complete. Auditors test samples, so they cannot guarantee there are no errors.", "e": "An unmodified audit opinion gives reasonable assurance that the accounts contain no material errors.", "f": "audit-basics.html", "n": "Audit basics", "l": "ind"}, {"t": "Reclaimable VAT", "m": "VAT paid on a purchase that a VAT-registered business can claim back from HMRC. It is not part of the asset’s cost.", "e": "A van costs £32,500 plus £6,500 VAT. The £6,500 is reclaimable, so the van’s cost is £32,500.", "f": "job-audit-fixed-asset-additions.html", "n": "Audit: fixed asset additions", "l": "job"}, {"t": "Recognise", "m": "To include an item as a figure in the financial statements (not just describe it in the notes).", "e": "A probable legal claim is recognised as a provision. A possible one is only disclosed.", "f": "ifrs-standards.html", "n": "IFRS standards", "l": "y3"}, {"t": "Recoverable amount", "m": "The higher of: (a) what an asset could be sold for, minus selling costs, and (b) the value of the cash it will bring in if the business keeps using it.", "e": "A machine could be sold for £90,000 or used to generate cash worth £87,829. The recoverable amount is £90,000.", "f": "ias-36-impairment.html", "n": "IAS 36: Impairment of assets", "l": "y3"}, {"t": "Reporting period end", "m": "The date the accounts are drawn up to, such as 31 December.", "e": "A company with a 31 December year end.", "f": "ias-10-events-after-reporting-period.html", "n": "IAS 10: Events after the reporting period", "l": "y3"}, {"t": "Research", "m": "Original work to find new knowledge. Its cost is always an expense.", "e": "Testing new coffee packaging materials in a laboratory.", "f": "ias-38-intangible-assets.html", "n": "IAS 38: Intangible assets", "l": "y3"}, {"t": "Residual value", "m": "The amount an asset is expected to be worth at the end of its useful life.", "e": "Machinery costs £20,000 and is expected to sell for £2,000 after 5 years. The residual value is £2,000.", "f": "depreciation.html", "n": "Depreciation and disposals", "l": "f"}, {"t": "Retained earnings", "m": "The total profits a company has made over its life and kept in the business, instead of paying them out as dividends.", "e": "Retained earnings of £12,000 in the statement of financial position.", "f": "statement-of-financial-position.html", "n": "Statement of financial position", "l": "f"}, {"t": "Retrospective", "m": "Applied as if the new treatment had always been used: last year’s figures and opening retained earnings are restated.", "e": "A policy change from FIFO to weighted average is shown in the comparatives too.", "f": "ias-8-policies-estimates-errors.html", "n": "IAS 8: Policies, estimates and errors", "l": "y3"}, {"t": "Revaluation model", "m": "Showing an asset in the accounts at its current market value (fair value), minus any depreciation charged since that valuation.", "e": "A building is revalued from £400,000 to £600,000 and shown at £600,000.", "f": "ias-16-property-plant-equipment.html", "n": "IAS 16: Property, plant and equipment", "l": "y3"}, {"t": "Revaluation surplus", "m": "The part of equity that holds the gains from revaluing assets upwards. The gains are not counted as profit.", "e": "A building revalued from £400,000 to £600,000 creates a £200,000 revaluation surplus.", "f": "company-balance-sheet-explained.html", "n": "Company statement of financial position", "l": "fs"}, {"t": "Revenue (sales)", "m": "The money a business earns from selling goods or services in its normal trading. Also called sales or turnover.", "e": "A café that sells £20,000 of coffee in a year has revenue of £20,000.", "f": "income-statement.html", "n": "Income statement", "l": "f"}, {"t": "Revenue expenditure", "m": "Day-to-day spending, including repairs and maintenance. It is an expense in the period it is incurred.", "e": "Repairing storm damage to a roof so it is back to its original condition.", "f": "job-audit-fixed-asset-additions.html", "n": "Audit: fixed asset additions", "l": "job"}, {"t": "Revenue grant", "m": "A grant related to income or running costs.", "e": "A grant towards the wages of trainees.", "f": "ias-20-government-grants.html", "n": "IAS 20: Government grants", "l": "y3"}, {"t": "Right to control", "m": "In a lease, when the customer decides how an asset is used and gets almost all of the benefit from using it.", "e": "Northwell decides when and how its leased gym machines are used, so it has the right to control them.", "f": "job-new-lease-ifrs16.html", "n": "Finance team: accounting for a new lease", "l": "job"}, {"t": "Right-of-use asset", "m": "The asset a lessee records for its right to use a leased item. It is depreciated over the lease.", "e": "A right-of-use asset of £97,405 for leased gym equipment.", "f": "ifrs-16-leases.html", "n": "IFRS 16: Lease calculations", "l": "y3"}, {"t": "ROCE", "m": "Return on capital employed: operating profit as a percentage of the long-term money invested in the business (equity plus long-term loans).", "e": "Operating profit £18,000 ÷ capital employed £120,000 = 15% ROCE.", "f": "ratio-analysis.html", "n": "Ratio analysis", "l": "y3"}, {"t": "Share capital", "m": "The money shareholders paid the company for its shares, measured at the shares’ nominal (face) value.", "e": "1,000,000 shares of £1 each gives share capital of £1,000,000.", "f": "company-balance-sheet-explained.html", "n": "Company statement of financial position", "l": "fs"}, {"t": "Spot rate", "m": "The exchange rate on the date of a transaction.", "e": "£1 = $1.25 on the day goods are bought.", "f": "ias-21-foreign-currency.html", "n": "IAS 21: Foreign currency transactions", "l": "y3"}, {"t": "Standalone selling price", "m": "The price at which a business would sell a good or service on its own, to a separate customer.", "e": "A phone sold on its own for £400 has a standalone selling price of £400.", "f": "ifrs-15-revenue.html", "n": "IFRS 15: Revenue in depth", "l": "y3"}, {"t": "STAR", "m": "A way to structure an answer to an interview question: Situation (the background), Task (what you had to do), Action (what you did), Result (what happened).", "e": "Situation: month-end was late. Task: find the cause. Action: I built a checklist. Result: it was finished on day one.", "f": "interview-prep.html", "n": "Interview prep", "l": "ind"}, {"t": "Strengths question", "m": "An interview question about what you enjoy and what you are naturally good at, to see whether the job suits you.", "e": "“What kind of task gives you the most energy?”", "f": "interview-prep.html", "n": "Interview prep", "l": "ind"}, {"t": "Subsidiary", "m": "A company controlled by another company (the parent), usually because the parent owns more than 50% of its voting shares.", "e": "P owns 80% of S, so S is P’s subsidiary.", "f": "consolidated-balance-sheet-explained.html", "n": "Consolidated statement of financial position", "l": "fs"}, {"t": "Suspense account", "m": "A temporary account used to hold the difference when a trial balance does not agree. It is cleared to zero once the errors are found and corrected.", "e": "Debits are £500 more than credits, so £500 is put in a suspense account until the error is found.", "f": "practical-bookkeeping.html", "n": "Practical bookkeeping", "l": "ind"}, {"t": "Tax base", "m": "The value of an asset or liability according to the tax rules, which can be different from its value in the accounts.", "e": "A machine is £80,000 in the accounts, but all its cost has already been claimed for tax, so its tax base is £0.", "f": "ias-12-deferred-tax.html", "n": "IAS 12: Deferred tax", "l": "y3"}, {"t": "Taxable total profits", "m": "A company’s accounting profit after the tax adjustments (adding back disallowed costs and deducting capital allowances). Corporation tax is charged on this figure.", "e": "Accounting profit £412,000 + additions £44,900 − capital allowances £55,000 = taxable total profits £401,900.", "f": "job-tax-vat-corporation-tax.html", "n": "Tax: VAT return and corporation tax", "l": "job"}, {"t": "Temporary difference", "m": "The difference between an item’s value in the accounts and its value for tax (its tax base). The difference will reverse in future years.", "e": "Accounts value £80,000 − tax base £0 = temporary difference of £80,000.", "f": "ias-12-deferred-tax.html", "n": "IAS 12: Deferred tax", "l": "y3"}, {"t": "Test count", "m": "A count of stock done by the auditor to check that the client’s count is accurate.", "e": "The auditor counts 236 bags on the shelf, while the count sheet says 260.", "f": "job-inventory-count.html", "n": "Audit: inventory count", "l": "job"}, {"t": "Time-apportion", "m": "To include only the part of a yearly amount that relates to a certain number of months.", "e": "A subsidiary bought on 1 April: include 9/12 of its annual revenue in the group accounts.", "f": "consolidated-profit-or-loss.html", "n": "Consolidated statement of profit or loss", "l": "y3"}, {"t": "Total comprehensive income", "m": "Profit for the year plus other comprehensive income. It is the total change in equity from the company’s performance in the year, before dividends and share issues.", "e": "Profit £480,000 + revaluation gain £150,000 = total comprehensive income £630,000.", "f": "company-profit-or-loss-explained.html", "n": "Company statement of profit or loss and OCI", "l": "fs"}, {"t": "Trade payables", "m": "Money the business owes to its suppliers for goods or services bought on credit. Also called creditors.", "e": "£3,200 owed to a coffee bean supplier for a delivery not yet paid for.", "f": "start-here.html", "n": "Start here", "l": ""}, {"t": "Trade receivables", "m": "Money customers owe the business for goods or services sold on credit. Also called debtors.", "e": "A café customer owes £2,000 for coffee delivered last week.", "f": "start-here.html", "n": "Start here", "l": ""}, {"t": "Transaction", "m": "Any business event involving money, such as a sale, a purchase or a payment. Each transaction is recorded in the accounts.", "e": "Paying £850 of rent is one transaction.", "f": "accounting-equation.html", "n": "The accounting equation", "l": "f"}, {"t": "Transaction price", "m": "The total amount a business expects to receive under a contract with a customer.", "e": "A contract for a machine, installation and service for £90,000 has a transaction price of £90,000.", "f": "ifrs-15-revenue.html", "n": "IFRS 15: Revenue in depth", "l": "y3"}, {"t": "Trial balance", "m": "A list of the balances on every account at a date, in a debit column and a credit column. Both columns should add up to the same total.", "e": "Debits total £5,850 and credits total £5,850, so the trial balance agrees.", "f": "trial-balance.html", "n": "Trial balance", "l": "f"}, {"t": "Unrealised profit (PURP)", "m": "Profit made on a sale between two group companies, where the goods are still held inside the group at the year end. It is removed in the group accounts because nobody outside the group has bought the goods yet.", "e": "The parent sells goods to its subsidiary at a £8,000 profit, and a quarter are still in stock. £2,000 is unrealised profit.", "f": "consolidated-profit-or-loss.html", "n": "Consolidated statement of profit or loss", "l": "y3"}, {"t": "Value in use", "m": "The value today of the cash an asset will bring in if the business keeps using it. It is worked out by discounting the future cash flows.", "e": "Cash flows of £40,000, £35,000 and £30,000 discounted at 10% give a value in use of £87,829.", "f": "ias-36-impairment.html", "n": "IAS 36: Impairment of assets", "l": "y3"}, {"t": "Variable consideration", "m": "Any part of a contract price that depends on something happening in future, such as a bonus, a penalty or a discount.", "e": "A £20,000 bonus paid only if the project finishes early.", "f": "ifrs-15-revenue.html", "n": "IFRS 15: Revenue in depth", "l": "y3"}, {"t": "Variance", "m": "The difference between an actual result and the budget.", "e": "Actual staff costs £43,900 − budget £41,000 = a variance of £2,900 (adverse).", "f": "job-month-end-close.html", "n": "Finance team: month-end close", "l": "job"}, {"t": "VAT return", "m": "A form a VAT-registered business sends to HMRC, usually every quarter, showing the VAT it charged, the VAT it can reclaim, and the difference to pay or be repaid.", "e": "Box 1 VAT on sales £37,280 − Box 4 VAT reclaimed £14,900 = Box 5 £22,380 to pay.", "f": "job-tax-vat-corporation-tax.html", "n": "Tax: VAT return and corporation tax", "l": "job"}, {"t": "Vouching", "m": "An audit test that starts with a figure in the accounts and checks it back to the original document, such as an invoice. It tests that the item is real.", "e": "The auditor picks a £148,000 addition and finds the supplier’s invoice for it.", "f": "job-audit-fixed-asset-additions.html", "n": "Audit: fixed asset additions", "l": "job"}, {"t": "Weighted average shares", "m": "The number of shares in issue, adjusted for how long each was in issue during the year.", "e": "1 million shares issued on 1 October count as 250,000 for the year.", "f": "ias-33-earnings-per-share.html", "n": "IAS 33: Earnings per share", "l": "y3"}, {"t": "Working papers", "m": "The auditor’s records of the work done, the evidence found and the conclusions reached. A reviewer must be able to follow them.", "e": "A working paper for receivables lists the balances tested, the evidence seen and the result.", "f": "audit-basics.html", "n": "Audit basics", "l": "ind"}, {"t": "Zero-rated", "m": "For VAT: a type of sale that is taxable, but at a rate of 0%. No VAT is charged, but the business can still reclaim VAT on its costs.", "e": "Goods exported outside the UK are zero-rated.", "f": "job-tax-vat-corporation-tax.html", "n": "Tax: VAT return and corporation tax", "l": "job"}];
